-- ============================================================
-- Little Dominicana — carga el Menú del día (Affiliates.DailyMenu) con su Weekly Menu oficial.
-- Requiere el deploy de feat/menu-del-dia (migración 20261029190000_AddDailyMenuAndBoardPanels).
-- Solo escribe la columna DailyMenu del afiliado; no toca productos ni precios.
-- Los precios NO van aquí: cada sección apunta a su plato (Combo del día, Sopas, Desayuno) y la TV
-- toma el precio y los tamaños de ese plato. Después se edita desde el panel → Pantallas → Menú del día.
-- Si algún plato no se encuentra (o hay dos), aborta sin guardar nada.
-- ============================================================
BEGIN;
DO $$
DECLARE
  v_aff uuid;
  v_id uuid;
  v_n int;
  v_json text := '{"note": "incluye arroz, habichuelas y una guarnición", "noteEn": "comes with rice, beans & a side", "days": {"monday": [{"name": "Arroz", "nameEn": "Rice", "kind": "List", "items": ["Arroz blanco", "Arroz con vegetales", "Arroz con pollo", "Arroz con habichuelas rojas"], "itemsEn": ["White Rice", "Rice with Vegetables", "Rice with Chicken", "Rice & Red Beans"]}, {"name": "Habichuelas", "nameEn": "Beans", "kind": "List", "items": ["Habichuelas rojas"], "itemsEn": ["Red Beans"]}, {"name": "Guarniciones", "nameEn": "Sides", "kind": "List", "items": ["Plátanos maduros", "Yuca", "Vegetales salteados"], "itemsEn": ["Sweet Plantains", "Yuca", "Stir-Fried Vegetables"]}, {"name": "Pollo", "nameEn": "Chicken", "kind": "Combo", "items": ["Pollo guisado", "Pollo al horno", "Pollo con vegetales"], "itemsEn": ["Stewed Chicken", "Baked Chicken", "Chicken & Vegetable Mix"], "productId": "__CHICKEN__"}, {"name": "Cerdo", "nameEn": "Pork", "kind": "Combo", "items": ["Pernil", "Cerdo guisado", "Tiras de cerdo"], "itemsEn": ["Pernil (Roasted Pork)", "Stewed Pork", "Pork Strips"], "productId": "__PORK__"}, {"name": "Res", "nameEn": "Beef", "kind": "Combo", "items": ["Res guisada", "Albóndigas", "Bistec encebollado"], "itemsEn": ["Stewed Beef", "Beef Meatballs", "Pepper Steak"], "productId": "__BEEF__"}, {"name": "Desayuno", "nameEn": "Breakfast", "kind": "Featured", "items": ["Mangú 3 golpes"], "itemsEn": ["Mangú 3 Golpes"], "productId": "__BF_MONDAY__", "from": "10:00", "to": "12:00"}], "tuesday": [{"name": "Arroz", "nameEn": "Rice", "kind": "List", "items": ["Arroz blanco", "Arroz con maíz", "Arroz con mariscos", "Arroz con guandules"], "itemsEn": ["White Rice", "Rice with Corn", "Rice with Seafood", "Rice & Peas"]}, {"name": "Habichuelas", "nameEn": "Beans", "kind": "List", "items": ["Habichuelas rojas", "Habichuelas rosadas"], "itemsEn": ["Red Beans", "Pink Beans"]}, {"name": "Guarniciones", "nameEn": "Sides", "kind": "List", "items": ["Plátanos maduros", "Batata frita", "Molondrones"], "itemsEn": ["Sweet Plantains", "Fried Sweet Potatoes", "Okra"]}, {"name": "Pollo", "nameEn": "Chicken", "kind": "Combo", "items": ["Pollo guisado", "Pollo al horno", "Pollo con vegetales"], "itemsEn": ["Stewed Chicken", "Baked Chicken", "Chicken & Vegetable Mix"], "productId": "__CHICKEN__"}, {"name": "Cerdo", "nameEn": "Pork", "kind": "Combo", "items": ["Pernil", "Cerdo guisado", "Tiras de cerdo"], "itemsEn": ["Pernil (Roasted Pork)", "Stewed Pork", "Pork Strips"], "productId": "__PORK__"}, {"name": "Res", "nameEn": "Beef", "kind": "Combo", "items": ["Res guisada", "Albóndigas", "Bistec encebollado"], "itemsEn": ["Stewed Beef", "Beef Meatballs", "Pepper Steak"], "productId": "__BEEF__"}, {"name": "Sopa del día", "nameEn": "Soup of the day", "kind": "Featured", "items": ["Sopa de res"], "itemsEn": ["Beef Soup"], "productId": "__SOUP_TUESDAY__"}, {"name": "Desayuno", "nameEn": "Breakfast", "kind": "Featured", "items": ["Espaguetis dominicanos con plátano verde"], "itemsEn": ["Dominican Spaghetti with Green Plantain"], "productId": "__BF_TUESDAY__", "from": "10:00", "to": "12:00"}], "wednesday": [{"name": "Arroz", "nameEn": "Rice", "kind": "List", "items": ["Arroz blanco", "Arroz con vegetales", "Arroz con cerdo", "Arroz con habichuelas negras"], "itemsEn": ["White Rice", "Rice with Vegetables", "Rice with Pork", "Rice & Black Beans"]}, {"name": "Habichuelas", "nameEn": "Beans", "kind": "List", "items": ["Habichuelas rojas", "Lentejas"], "itemsEn": ["Red Beans", "Lentils"]}, {"name": "Guarniciones", "nameEn": "Sides", "kind": "List", "items": ["Plátanos maduros", "Yuca", "Berenjena guisada"], "itemsEn": ["Sweet Plantains", "Yuca", "Stewed Eggplant"]}, {"name": "Pollo", "nameEn": "Chicken", "kind": "Combo", "items": ["Pollo guisado", "Pollo al horno", "Pollo con vegetales"], "itemsEn": ["Stewed Chicken", "Baked Chicken", "Chicken & Vegetable Mix"], "productId": "__CHICKEN__"}, {"name": "Cerdo", "nameEn": "Pork", "kind": "Combo", "items": ["Pernil", "Cerdo guisado", "Tiras de cerdo"], "itemsEn": ["Pernil (Roasted Pork)", "Stewed Pork", "Pork Strips"], "productId": "__PORK__"}, {"name": "Res", "nameEn": "Beef", "kind": "Combo", "items": ["Res guisada", "Albóndigas", "Bistec encebollado"], "itemsEn": ["Stewed Beef", "Beef Meatballs", "Pepper Steak"], "productId": "__BEEF__"}, {"name": "Sopa del día", "nameEn": "Soup of the day", "kind": "Featured", "items": ["Sopa de pollo"], "itemsEn": ["Chicken Soup"], "productId": "__SOUP_WEDNESDAY__"}, {"name": "Desayuno", "nameEn": "Breakfast", "kind": "Featured", "items": ["Yuca con bacalao y huevos"], "itemsEn": ["Yuca with Codfish & Eggs"], "productId": "__BF_WEDNESDAY__", "from": "10:00", "to": "12:00"}], "thursday": [{"name": "Arroz", "nameEn": "Rice", "kind": "List", "items": ["Arroz blanco", "Arroz con maíz", "Arroz con pollo", "Arroz con habichuelas rojas"], "itemsEn": ["White Rice", "Rice with Corn", "Rice with Chicken", "Rice & Red Beans"]}, {"name": "Habichuelas", "nameEn": "Beans", "kind": "List", "items": ["Habichuelas rojas", "Guandules con coco"], "itemsEn": ["Red Beans", "Pigeon Peas in Coconut Sauce"]}, {"name": "Guarniciones", "nameEn": "Sides", "kind": "List", "items": ["Plátanos maduros", "Batata frita", "Vegetales salteados"], "itemsEn": ["Sweet Plantains", "Fried Sweet Potatoes", "Stir-Fried Vegetables"]}, {"name": "Pollo", "nameEn": "Chicken", "kind": "Combo", "items": ["Pollo guisado", "Pollo al horno", "Pollo con vegetales"], "itemsEn": ["Stewed Chicken", "Baked Chicken", "Chicken & Vegetable Mix"], "productId": "__CHICKEN__"}, {"name": "Cerdo", "nameEn": "Pork", "kind": "Combo", "items": ["Pernil", "Cerdo guisado", "Tiras de cerdo"], "itemsEn": ["Pernil (Roasted Pork)", "Stewed Pork", "Pork Strips"], "productId": "__PORK__"}, {"name": "Res", "nameEn": "Beef", "kind": "Combo", "items": ["Res guisada", "Albóndigas", "Bistec encebollado"], "itemsEn": ["Stewed Beef", "Beef Meatballs", "Pepper Steak"], "productId": "__BEEF__"}, {"name": "Desayuno", "nameEn": "Breakfast", "kind": "Featured", "items": ["Mangú de yautía 3 golpes"], "itemsEn": ["Mangú de Yautía 3 Golpes"], "productId": "__BF_THURSDAY__", "from": "10:00", "to": "12:00"}], "friday": [{"name": "Arroz", "nameEn": "Rice", "kind": "List", "items": ["Arroz blanco", "Arroz con vegetales", "Arroz con mariscos", "Arroz con habichuelas negras"], "itemsEn": ["White Rice", "Rice with Vegetables", "Rice with Seafood", "Rice & Black Beans"]}, {"name": "Habichuelas", "nameEn": "Beans", "kind": "List", "items": ["Habichuelas rojas", "Habichuelas negras"], "itemsEn": ["Red Beans", "Black Beans"]}, {"name": "Guarniciones", "nameEn": "Sides", "kind": "List", "items": ["Plátanos maduros", "Yuca", "Molondrones"], "itemsEn": ["Sweet Plantains", "Yuca", "Okra"]}, {"name": "Pollo", "nameEn": "Chicken", "kind": "Combo", "items": ["Pollo guisado", "Pollo al horno", "Pollo con vegetales"], "itemsEn": ["Stewed Chicken", "Baked Chicken", "Chicken & Vegetable Mix"], "productId": "__CHICKEN__"}, {"name": "Cerdo", "nameEn": "Pork", "kind": "Combo", "items": ["Pernil", "Cerdo guisado", "Tiras de cerdo"], "itemsEn": ["Pernil (Roasted Pork)", "Stewed Pork", "Pork Strips"], "productId": "__PORK__"}, {"name": "Res", "nameEn": "Beef", "kind": "Combo", "items": ["Res guisada", "Albóndigas", "Bistec encebollado"], "itemsEn": ["Stewed Beef", "Beef Meatballs", "Pepper Steak"], "productId": "__BEEF__"}, {"name": "Rabo", "nameEn": "Oxtail", "kind": "Combo", "items": ["Rabo guisado"], "itemsEn": ["Stewed Oxtail"], "productId": "__OXTAIL__"}, {"name": "Sopa del día", "nameEn": "Soup of the day", "kind": "Featured", "items": ["Sopa de mondongo"], "itemsEn": ["Beef Tripe Soup"], "productId": "__SOUP_FRIDAY__"}, {"name": "Desayuno", "nameEn": "Breakfast", "kind": "Featured", "items": ["Salami guisado con yuca"], "itemsEn": ["Stewed Salami with Yuca"], "productId": "__BF_FRIDAY__", "from": "10:00", "to": "12:00"}], "saturday": [{"name": "Arroz", "nameEn": "Rice", "kind": "List", "items": ["Arroz blanco", "Arroz con vegetales", "Arroz con cerdo", "Arroz con guandules"], "itemsEn": ["White Rice", "Rice with Vegetables", "Rice with Pork", "Rice & Peas"]}, {"name": "Habichuelas", "nameEn": "Beans", "kind": "List", "items": ["Habichuelas rojas", "Guandules con coco"], "itemsEn": ["Red Beans", "Pigeon Peas in Coconut Sauce"]}, {"name": "Guarniciones", "nameEn": "Sides", "kind": "List", "items": ["Plátanos maduros", "Yuca", "Berenjena guisada"], "itemsEn": ["Sweet Plantains", "Yuca", "Stewed Eggplant"]}, {"name": "Pollo", "nameEn": "Chicken", "kind": "Combo", "items": ["Pollo guisado", "Pollo al horno", "Pollo con vegetales"], "itemsEn": ["Stewed Chicken", "Baked Chicken", "Chicken & Vegetable Mix"], "productId": "__CHICKEN__"}, {"name": "Cerdo", "nameEn": "Pork", "kind": "Combo", "items": ["Pernil", "Cerdo guisado", "Tiras de cerdo"], "itemsEn": ["Pernil (Roasted Pork)", "Stewed Pork", "Pork Strips"], "productId": "__PORK__"}, {"name": "Res", "nameEn": "Beef", "kind": "Combo", "items": ["Res guisada", "Albóndigas", "Bistec encebollado"], "itemsEn": ["Stewed Beef", "Beef Meatballs", "Pepper Steak"], "productId": "__BEEF__"}, {"name": "Chivo", "nameEn": "Goat", "kind": "Combo", "items": ["Chivo guisado"], "itemsEn": ["Stewed Goat"], "productId": "__OXTAIL__"}, {"name": "Sopa del día", "nameEn": "Soup of the day", "kind": "Featured", "items": ["Sancocho"], "itemsEn": ["Sancocho"], "productId": "__SOUP_SATURDAY__"}, {"name": "Desayuno", "nameEn": "Breakfast", "kind": "Featured", "items": ["Yuca con bacalao guisado"], "itemsEn": ["Yuca with Stewed Codfish"], "productId": "__BF_SATURDAY__", "from": "10:00", "to": "12:00"}]}}';
BEGIN
  SELECT "Id" INTO v_aff FROM "Affiliates" WHERE "Slug" = 'the-little-dominicana';
  IF v_aff IS NULL THEN RAISE EXCEPTION 'No existe el afiliado the-little-dominicana'; END IF;
  -- Cada plato se busca por categoría + día (no por nombre: los nombres ya se tradujeron) y debe
  -- haber exactamente 1.
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Combo del día' AND "Name" ILIKE '%Chicken%' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __CHICKEN__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Combo del día' AND "Name" ILIKE '%Chicken%' AND "Status" = 'Active';
  v_json := replace(v_json, '__CHICKEN__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Combo del día' AND "Name" ILIKE '%Pork%' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __PORK__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Combo del día' AND "Name" ILIKE '%Pork%' AND "Status" = 'Active';
  v_json := replace(v_json, '__PORK__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Combo del día' AND "Name" ILIKE '%Beef%' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __BEEF__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Combo del día' AND "Name" ILIKE '%Beef%' AND "Status" = 'Active';
  v_json := replace(v_json, '__BEEF__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Combo del día' AND "Name" ILIKE '%Oxtail%' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __OXTAIL__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Combo del día' AND "Name" ILIKE '%Oxtail%' AND "Status" = 'Active';
  v_json := replace(v_json, '__OXTAIL__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Soups' AND "WeekDays" = 'tuesday' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __SOUP_TUESDAY__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Soups' AND "WeekDays" = 'tuesday' AND "Status" = 'Active';
  v_json := replace(v_json, '__SOUP_TUESDAY__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Soups' AND "WeekDays" = 'wednesday' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __SOUP_WEDNESDAY__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Soups' AND "WeekDays" = 'wednesday' AND "Status" = 'Active';
  v_json := replace(v_json, '__SOUP_WEDNESDAY__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Soups' AND "WeekDays" = 'friday' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __SOUP_FRIDAY__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Soups' AND "WeekDays" = 'friday' AND "Status" = 'Active';
  v_json := replace(v_json, '__SOUP_FRIDAY__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Soups' AND "WeekDays" = 'saturday' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __SOUP_SATURDAY__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Soups' AND "WeekDays" = 'saturday' AND "Status" = 'Active';
  v_json := replace(v_json, '__SOUP_SATURDAY__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'monday' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __BF_MONDAY__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'monday' AND "Status" = 'Active';
  v_json := replace(v_json, '__BF_MONDAY__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'tuesday' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __BF_TUESDAY__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'tuesday' AND "Status" = 'Active';
  v_json := replace(v_json, '__BF_TUESDAY__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'wednesday' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __BF_WEDNESDAY__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'wednesday' AND "Status" = 'Active';
  v_json := replace(v_json, '__BF_WEDNESDAY__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'thursday' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __BF_THURSDAY__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'thursday' AND "Status" = 'Active';
  v_json := replace(v_json, '__BF_THURSDAY__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'friday' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __BF_FRIDAY__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'friday' AND "Status" = 'Active';
  v_json := replace(v_json, '__BF_FRIDAY__', v_id::text);
  SELECT count(*) INTO v_n FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'saturday' AND "Status" = 'Active';
  IF v_n <> 1 THEN RAISE EXCEPTION 'Esperaba 1 plato para __BF_SATURDAY__, encontré %', v_n; END IF;
  SELECT "Id" INTO v_id FROM "Products" WHERE "AffiliateId" = v_aff AND "Category" = 'Breakfast' AND "WeekDays" = 'saturday' AND "Status" = 'Active';
  v_json := replace(v_json, '__BF_SATURDAY__', v_id::text);
  IF position('__' in v_json) > 0 THEN RAISE EXCEPTION 'Quedó algún plato sin enlazar'; END IF;
  UPDATE "Affiliates" SET "DailyMenu" = v_json WHERE "Id" = v_aff;
END $$;
COMMIT;

-- Verificación: días cargados y cuántas secciones tiene cada uno (debe dar lunes..sábado).
SELECT d.key AS dia, jsonb_array_length(d.value) AS secciones
FROM "Affiliates" a, jsonb_each(a."DailyMenu"::jsonb -> 'days') d
WHERE a."Slug" = 'the-little-dominicana'
ORDER BY array_position(ARRAY['monday','tuesday','wednesday','thursday','friday','saturday','sunday'], d.key);
